@@ -13,3 +13,14 @@ export async function addItem(item) {
   const id = Math.max(0, ...items.map((i) => i.id)) + 1;
   return saveItem({ tags: [], unit: "", ...item, id });
 }
+
+/** Takes `n` from the `qty` of item `id` and returns the updated item. */
+export async function useItem(id, n = 1) {
+  const items = await fetchItems();
+  const item = items.find((i) => i.id === id);
+  if (!item) throw new Error(`Unknown item id: ${id}.`);
+  if (!Number.isInteger(n) || n < 0 || n > item.qty) {
+    throw new Error("Insufficient quantity.");
+  }
+  return saveItem({ ...item, qty: item.qty - n });
+}
